const raw = items[0].json.message?.content ?? items[0].json.choices?.[0]?.message?.content ?? '';
let parsed;
try {
  const cleaned = raw.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  return [{ json: { ok: false, message: 'AI returned invalid JSON: ' + e.message, raw } }];
}
return [{ json: { ok: true, settlement: parsed.kind ? parsed : null, stores: parsed.stores ?? null, store: parsed.store ?? null, _parsed: parsed } }];
